 hidrógeno en tanques de tipo IV, por ser más eficientes.","start_date":"01/02/2020","end_date":"31/07/2021","feder_operation_cost":327145.13,"eu_cofinancing_percent":100.0,"province":"Zaragoza","municipality":"Muela, La","municipality_code":"50182","intervention":"071 Desarrollo y promoción de empresas especializadas en prestación de servicios que contribuyen a la economía con bajas emisiones de carbono y a la resistencia al cambio climático (incluyendo el apoyo a dichos servicios)","source_url":"https://www.dgfc.sepg.hacienda.gob.es/sitios/dgfc/es-ES/loFEDER1420/porFEDER/Documents/LO-AR.pdf#page=1145","source_file":"feder-aragon-2014-2020-20250529.pdf","source_page":1145,"source_updated":"2025-05-29"}],"match_method":"","feder_cost_reconciled_to_grant":null,"scope_note":"El coste de la operación FEDER no es la inversión subvencionable del proyecto. Las actuaciones de otros años son antecedentes de la empresa, no el proyecto de esta solicitud.","identity_sources":[],"fields":{"nif":"","project_description":"","municipality":"","province":"","project_start_dates":"","project_end_dates":""}},"province":null},{"import_key":"443d4aebfe50f9e19eccd1b8","enrichment":{"version":1,"reviewed_at":"2026-11-20","project_operations":[],"related_company_operations":[],"match_method":"","feder_cost_reconciled_to_grant":null,"scope_note":"El coste de la operación FEDER no es la inversión subvencionable del proyecto. Las actuaciones de otros años son antecedentes de la empresa, no el proyecto de esta solicitud.","identity_sources":[],"fields":{"nif":"","project_description":"","municipality":"","province":"","project_start_dates":"","project_end_dates":""}},"province":null},{"import_key":"edf29362aee1379b42cedd49","enrichment":{"version":1,"reviewed_at":"2026-11-20","project_operations":[],"related_company_operations":[],"match_method":"","feder_cost_reconciled_to_grant":null,"scope_note":"El coste de la operación FEDER no es la inversión subvencionable del proyecto. Las actuaciones