vince":"","project_start_dates":"","project_end_dates":""}},"province":null},{"import_key":"f09f35070fa8c9c6db575225","enrichment":{"version":1,"reviewed_at":"2026-11-20","project_operations":[{"operation_code":"D2021120","year":2021,"line":"IDIS-REACT","beneficiary":"ONIAD ADVERTISING, S.L.","feder_beneficiary_id":"ES51EL71","operation_name":"ONIAD ADVERTISING, S.L.","description":"\"El objetivo del proyecto es el desarrollo de una herramienta de marketing digital capaz de mejorar el rendimiento de las campañas hipersegmentadas a partir de la toma de decisiones de manera automática, con un incremento del retorno de la inversión publicitaria. La particularidad del proyecto es que no solo se basaba en el estudio de datos técnicos de las campañas, sino que también incluía datos de negocio procedentes del CRM. Mediante la ejecución del proyecto se pretende cambiar la forma de diseñar, producir, comercializar y generar valor a partir de los servicios relacionados. Los avances tecnológicos presentes en el sistema desarrollado transforman los procesos y modelos de negocio en todos los sectores y crean nuevos patrones industriales, a medida que cambian las cadenas de valor a nivel global. Con este proyecto, se pretende avanzar en el ámbito de la Estrategia Aragón Industria 4.0 a partir de la elaboración de una estrategia marcada por la Industria 4.0 utilizando Big Data, análisis de datos e Inteligencia Artificial. Para la consecución del presente proyecto se acometen los siguientes objetivos técnicos: 1. Desarrollo de un nuevo sistema para mejorar el rendimiento de las campañas hipersegmentadas para contar con una mayor cantidad de datos y alimentar el algoritmo de Machine Learning. 2. Gestión y análisis de los datos en una plataforma analítica para obtener una mayor eficiencia del proceso de marketing digital. 3. Integración de un nuevo software para facilitar la compra de publicidad a los anunciantes debido a la mejora de la visibilidad a partir de la elaboración de un sistema de recopilación y almacenaje de datos. 4. Optimización automática a la hora de modificar las campañas en función de los resultados y tomar decisiones sobre el precio de puja para un medio en un momento concreto, gracias a la Inteligencia artificial\"","start_date":"01/02/2020","end_date":"31/07/2021","feder_operation_cost":29250.0,"eu_cofinancing_percent":100.0,"province":"Zaragoza","municipality":"Cuarte de Huerva","municipality_code":"50089","intervention":"004 Inversión productiva relativas a la cooperación entre grandes empresas y PYME para desarrollar productos y servicios en tecnologías de la información y las comunicaciones (TIC), comercio electrónico y mayor demanda de TIC.","source_url":"https://www.dgfc.sepg.hacienda.gob.es/sitios/dgfc/es-ES/loFEDER1420/porFEDER/Documents/LO-AR.pdf#page=539","source_file":"feder-aragon-2014-2020-20250529.pdf","source_page":539,"source_updated":"2025-05-29"}],"related_company_operations":[],"match_method":"beneficiario exacto normalizado + anualidad + línea + importe conciliado (tolerancia 1 €)","feder_cost_reconciled_to_grant":true,"scope_note":"El coste de la operación FEDER no es la inversión subvencionable del proyecto. Las actuaciones de otros años son antecedentes de la empresa, no el proyecto de esta solicitud.","identity_sources":[],"fields":{"nif":"","project_description":"\"El objetivo del proyecto es el desarrollo de una herramienta de marketing digital capaz de mejorar el rendimiento de las campañas hipersegmentadas a partir de la toma de decisiones de manera automática, con un incremento del retorno de la inversión publicitaria. La particularidad del proyecto es que no solo se basaba en el estudio de datos técnicos de las campañas, sino que también incluía datos de negocio procedentes del CRM. Mediante la ejecución del proyecto se pretende cambiar la forma de diseñar, producir, comercializar y generar valor a partir de los servicios relacionados. Los avances tecnológicos presentes en el sistema desarrollado transforman los procesos y modelos de negocio en todos los sectores y crean nuevos patrones industriales, a medida que cambian las cadenas de valor a nivel global. Con este proyecto, se pretende avanzar en el ámbito de la Estrategia Aragón Industria 4.0 a partir de la elaboración de una estrategia marcada por la Industria 4.0 utilizando Big Data, análisis de datos e Inteligencia Artificial. Para la consecución del presente proyecto se acometen los siguientes objetivos técnicos: 1. Desarrollo de un nuevo sistema para mejorar el rendimiento de las campañas hipersegmentadas para contar con una mayor cantidad de datos y alimentar el algoritmo de Machine Learning. 2. Gestión y análisis de los datos en una plataforma analítica para obtener una mayor eficiencia del proceso de marketing digital. 3. Integración de un nuevo software para facilitar la compra de publicidad a los anunciantes debido a la mejora de la visibilidad a partir de la elaboración de un sistema de recopilación y almacenaje de datos. 4. Optimización automática a la hora de modificar las campañas en función de los resultados y tomar decisiones sobre el precio de puja para un medio en un momento concreto, gracias a la Inteligencia artificial\"","municipality":"Cuarte de Huerva","province":"Zaragoza","project_start_dates":"01/02/2020","project_end_dates":"31/07/2021"}},"province":"Zaragoza"},{"import_key":"ba6524341131fccb513808ce","enrichment":{"version":1,"reviewed_at":"2026-11-20","project_operations":[],"related_company_operations":[{"operation_code":"V2021304","year":2021,"line":"IDIS-REACT","beneficiary":"TEVA PHARMA S.L.U.","feder_beneficiary_id":"ES51LX56","operation_name":"TEVA PHARMA, S.L.","description":"Ell presente proyecto se incluye la inversión en la línea de acondicionamiento del fármaco Venlafaxina, incorporando una nueva máquina llenadora de cápsulas de forma automática y eficiente","start_date":"01/02/2020","end_date":"31/07/2021","feder_operation_cost":2204342.98,"eu_cofinancing_perce