ienda.gob.es/sitios/dgfc/es-ES/loFEDER1420/porFEDER/Documents/LO-AR.pdf#page=105","source_file":"feder-aragon-2014-2020-20250529.pdf","source_page":105,"source_updated":"2025-05-29"},{"operation_code":"2020024","year":2020,"line":"TDI-FEDER (antecedente)","beneficiary":"ELECTROINGENIERIA INDUSTRIAL XCLC","feder_beneficiary_id":"ES51Q041","operation_name":"ELECTROINGENIERIA INDUSTRIAL XCLC, S.L.","description":"los proyectos de la empresa consisten en diseños y automatizaciones para el control y monitorización de las instalaciones de proceso de sus clientes.","start_date":"01/10/2019","end_date":"31/12/2020","feder_operation_cost":69361.74,"eu_cofinancing_percent":50.0,"province":"Zaragoza","municipality":"Zaragoza","municipality_code":"50297","intervention":"001 Inversión productiva genérica en pequeñas y medianas –empresas («PYME»)","source_url":"https://www.dgfc.sepg.hacienda.gob.es/sitios/dgfc/es-ES/loFEDER1420/porFEDER/Documents/LO-AR.pdf#page=167","source_file":"feder-aragon-2014-2020-20250529.pdf","source_page":167,"source_updated":"2025-05-29"},{"operation_code":"D2022048","year":2022,"line":"IDIS-REACT","beneficiary":"ELECTROINGENIERIA INDUSTRIAL XCLC","feder_beneficiary_id":"ES51Q041","operation_name":"ELECTROINGENIERIA INDUSTRIAL XCLC, S.L.","description":"Los proyectos de la empresa suelen consistir en diseños y automatizaciones para el control y monitorizacion de las instalaciones de proceso de sus clientes. Para realizar nuevas lineas de producción y máquinas de forma más rápida manteniendo el alto nivel de calidad, es necesario optimizar el flujo de trabajo de ingeniería en la automatización y reducir al mínimo los tiempos de configuración y puesta en marcha de nuevas líneas de producción. Esto es posible mediante una simulación en tiempo real y la emulación para una verificación amplia de soluciones de automatización. Las inversiones que se pretenden realizar permitirán a la empresa simular mediante una plataforma de simulación homogénea de gran capacidad con la que se puede, adicionalmente, implementar la puesta en marcha virtual de la tecnología de automatización de sistemas, máquinas y procesos, en línea con los principio de la Industria 4.0. La simulación interactiva basada en la física verifica el funcionamiento correcto de la maquinaria. Esta verificación temprana ayuda a detectar y corregir errores en las fases en que resultan más económicos de resolver.","start_date":"01/02/2021","end_date":"31/08/2022","feder_operation_cost":4121.0,"eu_cofinancing_percent":100.0,"province":"Zaragoza","municipality":"Zaragoza","municipality_code":"50297","intervention":"004 Inversión productiva relativas a la cooperación entre grandes empresas y PYME para desarrollar productos y servicios en tecnologías de la información y las comunicaciones (TIC), comercio electrónico y mayor demanda de TIC.","source_url":"https://www.dgfc.sepg.hacienda.gob.es/sitios/dgfc/es-ES/loFEDER1420/porFEDER/Documents/LO-AR.pdf#page=580","source_file":"feder-aragon-2014-2020-20250529.pdf","source_page":580,"source_updated":"2025-05-29"}],"match_method":"beneficiario exacto normalizado + anualidad + línea + importe conciliado (tolerancia 1 €)","feder_cost_reconciled_to_grant":true,"scope_note":"El coste de la operación FEDER no es la inversión subvencionable del proyecto. Las actuaciones de otros años son antecedentes de la empresa, no el proyecto de esta solicitud.","identity_sources":[],"fields":{"nif":"","project_description":"La inversión permitirá a la empresa contribuir a la expansión de los principios de la industria 4,0 en sus propios clientes, aprovechando las sinergias y ventajas que otorga la tecnologia. El uso de la tecnologia adquirida permite optimizar la calidad de los proyectos de automatización sin riesgos para la planta real y reducir costes o generar ahorros en las etapas de fabricación y puesta en marcha de las maquinas","municipality":"Zaragoza","province":"Zaragoza","project_start_dates":"01/02/2020","project_end_dates":"31/07/2021"}},"province":"Zaragoza"},{"import_key":"be07664384b3434721d8d2d6","enrichment":{"version":1,"reviewed_at":"2026-11-20","project_operations":[{"operation_code":"D2021012","year":2021,"line":"IDIS-REACT","beneficiary":"BIT & BRAIN TECHNOLOGIES, S.L.","feder_beneficiary_id":"ES51F865","operation_name":"BIT & BRAIN TECHNOLOGIES, S.L.","description":"El objetivo principal del proyecto es llevar a cabo toda la investigación y desarrollo de un nuevo producto y servicio de neurotecnología para el diagnóstico y tratamiento de los trastornos del sueño, basada en nuevos materiales para textiles conductores, herramientas de inteligencia artificial y computación en la nube. Por un lado se llevará a cabo una investigación en un dispositivo de medición de EEG, en la frente, accesible y fiable basado en tejidos inteligentes para la monitorización autogesionada/administrada del sueño, el cual ademas incluye un software de inteligencia artificial ubicado en la nube para el procesamiento automatizado de datos de EEG y la evaluación de la calidad del sueño (evaluación automatizada del sueño). Por otro lado, se llevará a cabo una investigación en un dispositivo de neurotecnología para el tratamiento del insomnio. Este equipo de EEG (igual que el del objetivo anterior está basado en tejidos inteligentes e incluye un software de inteligencia artificial ubicado en la nube para la personalización del tratamiento.","start_date":"01/02/2020","end_date":"31/07/2021","feder_operation_cost":69199.0,"eu_cofinancing_percent":100.0,"province":"Zaragoza","municipality":"Zaragoza","municipality_code":"50297","intervention":"004 Inversión productiva relativas a la cooperación entre grandes empresas y PYME para desarrollar productos y servicios en tecnologías de la información y las comunicaciones (TIC), comercio electrónico y mayor demanda de TIC.","source_url":"https://www.dgfc.sepg.hacienda.gob.es/sitios/dgfc/es-ES/loFEDER1420/porFEDER/Documents/LO-AR.pdf#page=452","source_file":"feder-arago